import { Container, createResolve } from "@owja/ioc";

import { createBinders } from "./createBinders";

export const createContext = <
  Mapping extends {
    [k: string]: any;
  }
>() => {
  const container = new Container();
  return {
    bind: createBinders<Mapping>(container),
    resolve: createResolve<Mapping>(container),
  };
};
