import { Logger } from "@vendoo/common/context/shared/resolve";
import { PortLikeType } from "@vendoo/extension-v3/src/serviceWorker/services/types";

export const getEventForwarder = (port: PortLikeType) => {
  let timeoutId: NodeJS.Timeout;
  const delay = 2000;

  return (event: chrome.webRequest.WebRequestBodyDetails) => {
    const logger = Logger().extend("listener");

    logger.info("Forwarding request events", { portName: port.name });

    if (timeoutId) clearTimeout(timeoutId);
    timeoutId = setTimeout(
      () =>
        port.postMessage({
          type: "requestEvent",
          name: "webRequest.onBeforeRequest",
          payload: event,
        }),
      delay
    );
  };
};
