import { LoggerType } from "@vendoo/common/logger2/constructor";
import { Logger } from "@vendoo/common/context/shared/resolve";
import { MixedError, VendooError, VendooErrorCtxType } from "./vendoo";
import { AxiosError } from "axios";
import { ValidationError } from "yup";
import { ZodError } from "zod";
import errorDictionary from "../dictionary/errors";
import randomStr from "../utils/random-str";

export interface HandledErrorType {
  alertTeam: boolean;
  allowRetry: boolean;
  context: VendooErrorCtxType;
  errorID: string;
  monitorCode?: string;
  httpCode: number;
  message: string;
  rawMessage: string;
  name?: string;
}

export type NullableErrorType = HandledErrorType | null;

export const isHandledErrorType = (err: any): err is HandledErrorType => {
  return (
    err &&
    typeof err === "object" &&
    "alertTeam" in err &&
    "allowRetry" in err &&
    "context" in err &&
    "errorID" in err &&
    "httpCode" in err &&
    "message" in err &&
    "rawMessage" in err
  );
};

const isVendooAxiosError = (
  err: any
): err is AxiosError<{ vendooError: HandledErrorType }> => {
  return (
    err &&
    err.isAxiosError &&
    err.response &&
    err.response.data &&
    err.response.data.vendooError
  );
};

const isAxiosNetworkError = (err: any) => {
  return err && err.isAxiosError && err.request && !err.response;
};

const isTimeoutError = (err: any) =>
  err &&
  (err.message.includes("The request timed out") ||
    stringify(err).includes("The request timed out"));

const toError = (err: any): Error => {
  if (
    !(err instanceof Error) &&
    (typeof err !== "object" || !("name" in err))
  ) {
    return new Error(`Non-error exception: ${stringify(err)}`);
  } else {
    return err;
  }
};

export const stringify = (err: any) => {
  try {
    return (err?.toString() ?? "") + " - " + JSON.stringify(err, null, 2);
  } catch (_err) {
    return "";
  }
};

// eslint-disable-next-line complexity
export const parseException = (
  err: any,
  defaultMessage = errorDictionary.unhandled,
  logger?: LoggerType
): HandledErrorType => {
  let errorID = "E" + randomStr(7);
  let monitorCode: string | undefined;
  let message = defaultMessage;
  let httpCode = 500;
  let allowRetry = false;
  let alertTeam = true;
  let name = err?.name ?? "Error";
  let context: VendooErrorCtxType | undefined;

  if (isVendooAxiosError(err)) {
    // Transform Axios errors
    const vendooServerError = err.response!.data.vendooError;
    message = vendooServerError.message;
    allowRetry = vendooServerError.allowRetry;
    httpCode = vendooServerError.httpCode;
    errorID = vendooServerError.errorID ?? errorID;
    alertTeam = false;
  } else if (isAxiosNetworkError(err) || isTimeoutError(err)) {
    // Transform generic network error
    message = errorDictionary.networkError;
    allowRetry = true;
    alertTeam = false;
  } else if (err instanceof ValidationError) {
    // Transform Yup errors
    message = err.message;
    httpCode = 400;
    alertTeam = false;
  } else if (err instanceof ZodError) {
    // Transform Yup errors
    message = errorDictionary.genericValidation;
    httpCode = 400;
    alertTeam = false;
    if (context) {
      context["issues"] = JSON.stringify(err.issues);
    } else {
      context = { issues: JSON.stringify(err.issues) };
    }
  } else if (err instanceof VendooError) {
    // Maps from an internal handled error
    message = err.message;
    httpCode = err.options.httpCode;
    allowRetry = err.options.allowRetry;
    alertTeam = err.options.alertTeam;
    context = err.ctx;

    if (context) {
      const originalErrorMessage = err.ctx?.originalErrorMessage;
      context = {
        ...context,
        originalMessage: originalErrorMessage ?? message,
      };

      if (logger && !originalErrorMessage) {
        logger.debug("Missing original error: ", err);
      }
    }

    errorID = err.options.errorID || errorID;
    monitorCode = err.options.monitorCode;
  } else if (err instanceof MixedError) {
    const details = err.errors.map(e =>
      handleException(e, defaultMessage, logger)
    );
    const userErrors = details.filter(d => !d.alertTeam);
    const unhandledErrors = details.filter(d => d.alertTeam);

    errorID = unhandledErrors.map(d => d.errorID).join("/");

    const getInTouch = unhandledErrors.length
      ? `${errorDictionary.getInTouch} (Error Code: ${errorID})`
      : "";
    const userErrorMessages = userErrors.length
      ? ": " + userErrors.map(d => d.rawMessage).join("; ") + ". "
      : ". ";

    message = `${MixedError.multipleErrorsMessagePrefix}${userErrorMessages}${getInTouch}`;
    httpCode = details.find(d => d.httpCode)?.httpCode ?? httpCode;
    allowRetry = details.some(d => d.allowRetry);
    context = details.reduce(
      (a, d) => Object.assign(a, d.context),
      {} as VendooErrorCtxType
    );
    alertTeam = false; // Inner errors were already alerted
  } else if ("name" in err && `${err.name}`.startsWith("Firebase")) {
    // Maps from an internal handled error
    message = err.message;
  }

  // Adds more metadata to context for all errors
  if (!context) context = {};

  if (err?.code && !context.code) {
    context.code = err.code;
  }
  if (
    err?.message &&
    err.message !== message &&
    (!context.originalMessage || !context.originalErrorMessage)
  ) {
    context = {
      ...context,
      originalMessage: err.message,
    };
  }

  if (!context.originalError) {
    context.originalError = stringify(err);
  }

  if (!alertTeam && !context.parsedMessage) {
    context.parsedMessage = message;
  }

  const res: HandledErrorType = {
    message: alertTeam ? `${message} (Error Code: ${errorID})` : message,
    rawMessage: message,
    allowRetry,
    context,
    errorID,
    httpCode,
    // Extra data
    alertTeam,
    name,
  };
  if (monitorCode) {
    res.monitorCode = monitorCode;
  }
  return res;
};

/**
 * Tracks any kind of error that happened in the app
 *
 * Returns a json representation of a vendooError
 * - with the correct message for the user
 */
export const handleException = (
  err: any,
  defaultMessage = errorDictionary.unhandled,
  logger: LoggerType = Logger()
): HandledErrorType => {
  // if the error was already handled before, return it
  if (isHandledErrorType(err)) {
    return err;
  }
  const error = toError(err);
  const parsed = parseException(error, defaultMessage, logger);

  if (parsed.alertTeam) {
    logger.exception(error, parsed.errorID, parsed.context);
  } else {
    logger.warn(error.message, parsed.context, error);
  }

  return parsed;
};
