import { Container } from "@owja/ioc";

export const createBinders = <
  Types extends {
    [k: string]: any;
  }
>(
  container: Container
) => {
  type Options = {
    inSingletonScope(): void;
  };

  return {
    value<T extends keyof Types>(symbol: T, value: Types[T]): void {
      return container.bind<Types[T]>(symbol as symbol).toValue(value);
    },

    factory<T extends keyof Types>(
      symbol: T,
      factory: () => Types[T]
    ): Options {
      return container.bind<Types[T]>(symbol as symbol).toFactory(factory);
    },

    class<T extends keyof Types>(
      symbol: T,
      newable: {
        new (...args: any[]): Types[T];
      }
    ): Options {
      return container.bind<Types[T]>(symbol as symbol).to(newable);
    },

    rebind: {
      /** Try not to use this, we are trying to figure out if this make sense or not */
      value<T extends keyof Types>(symbol: T, value: Types[T]): void {
        return container.rebind<Types[T]>(symbol as symbol).toValue(value);
      },
    },
  };
};
