const LETTERS = "abcdefghijklmnopqrstuvwxyz";

const RANDOM_STR_LOWER_DICT = `0123456789${LETTERS}`;
export const RANDOM_STR_FULL_DICT = `0123456789${LETTERS.toUpperCase()}${LETTERS}`;

export default function randomStr(
  len: number = 8,
  strDict: string = RANDOM_STR_LOWER_DICT
) {
  const dict = strDict.split("");

  return [...new Array(len)]
    .map(() => dict[Math.floor(Math.random() * dict.length)])
    .join("");
}
