import { VendooError } from "@vendoo/common/errors/vendoo";

// Types
import { BinaryPropsType } from "../types";
import isU8bytesUrl from "./isU8bytesUrl";

export const binary = ({ data, type, file }: BinaryPropsType) => {
  if (!isU8bytesUrl(data))
    throw new VendooError("Image format not allowed to transform");

  // Default params
  file = file ?? ({} as NonNullable<BinaryPropsType["file"]>);
  file.mimetype = file.mimetype ?? "image/jpeg";
  file.filename =
    file.filename ?? `file_${Math.floor(Math.random() * 10)}.jpeg`;

  const u8bytes = atob(data.split(",").pop()!)
    .split("")
    .map(c => c.charCodeAt(0));
  const u8arr = new Uint8Array(u8bytes);

  if (type === "file")
    return new File([u8arr], file.filename, { type: file.mimetype });

  return new Blob([u8arr], { type: file.mimetype });
};
