import {
  AutopilotInstructionType,
  AutopilotNotifySingleRequestType,
  AutopilotPullResponseSchema,
  AutopilotPullSourceType,
  AutopilotNotifyBundleRequestType,
} from "@vendoo/common/schemas/server/autopilot";
import { AnyCommand } from "@vendoo/extension-v3/src/serviceWorker/services/types";
import { RequestErrorResponseType } from "./types";
import { handleException } from "@vendoo/common/errors/handle";
import { Logger } from "@vendoo/common/context/shared/resolve";
import { LoggerType } from "@vendoo/common/logger2/constructor";
import { createRegionHeader } from "@vendoo/common/request/loadBalancer";

import { VendooExtensionSessionStore } from "./extensionSession";

const getVendooServerBasePath = (path: string) =>
  process.env.VENDOO_SERVER_ENDPOINT + path;

const sendServerRequest = async (request: Request) => {
  try {
    const response = await fetch(request);
    return await response.json();
  } catch (err) {
    const error = handleResponseError(err);
    throw error;
  }
};

const getRequestOptions = async ({
  deviceId,
  source,
  instruction,
  response,
}: {
  deviceId: string;
  source: AutopilotPullSourceType;
  instruction?: AutopilotInstructionType;
  response?: AnyCommand;
}): Promise<RequestInit> => {
  const region = await VendooExtensionSessionStore().getRegion();
  return {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...createRegionHeader(region),
    },
    body: JSON.stringify({
      deviceId: deviceId,
      timestamp: Date.now(),
      instruction,
      response,
      source,
    } as AutopilotNotifySingleRequestType),
  };
};

const getBundleRequestOptions = async (
  bundle: AutopilotNotifyBundleRequestType
) => {
  const region = await VendooExtensionSessionStore().getRegion();
  return {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...createRegionHeader(region),
    },
    body: JSON.stringify(bundle),
  };
};

function handleResponseError(err: RequestErrorResponseType) {
  if (!err.response) return new Error(err.message);

  const errorMsg = err.response.statusText || "Internal server error";
  const error = new Error(errorMsg);
  error["status"] = 500;
  error["description"] = err.response.data ? err.response.data : null;
  return error;
}

function assertResponse(
  res: AutopilotPullResponseSchema
): AutopilotPullResponseSchema {
  const responsePayload = res;

  // when we have an error on the server side we are returning
  // a valid response with a VendooError
  // this way we are going to parse it to an Error and throw it forward
  if (!responsePayload.success && responsePayload.vendooError) {
    const { vendooError } = responsePayload;
    const error = new Error(vendooError.message);
    error["response"] = {
      statusText: vendooError.message,
      data: JSON.stringify(vendooError),
    };
    throw error as RequestErrorResponseType;
  }

  return responsePayload;
}

export const setLastRun = () =>
  Promise.resolve(chrome.storage.local.set({ lastRun: Date.now() }));

/**
 * See DR: https://www.notion.so/vendoo/Decision-flow-control-using-chrome-storage-on-Extension-pull-queue-d14cf35319744e1986c72047fb8c598d
 */
export const getLastRun = ({
  logger,
}: {
  logger: LoggerType;
}): Promise<number | null> =>
  new Promise(resolve =>
    chrome.storage.local.get(res => {
      if (!res.lastRun) {
        if (chrome.runtime?.lastError?.message) {
          logger.warn("Error while getting lastRun", {
            error: chrome.runtime?.lastError?.message,
          });
        }

        // if error or unset lets return null
        resolve(null);
        return;
      }

      resolve(res.lastRun as number);
    })
  );

export const captureException = (fn: () => any) => {
  return async () => {
    try {
      await Promise.resolve(fn());
    } catch (err) {
      console.error(err); // If Logger is unavailable
      console.warn("Parsed error", handleException(err, undefined, Logger()));
    }
  };
};

/**
 * Reaches to the server to pull instructions.
 * Instructions are manage on the server side according to the deviceID.
 */
export async function queryCommands(
  deviceId: string,
  source: AutopilotPullSourceType
): Promise<AutopilotPullResponseSchema> {
  const canRun = await VendooExtensionSessionStore().prepareSessionCookies();
  if (!canRun) return { success: false, instructions: [] };

  const options: RequestInit = await getRequestOptions({
    deviceId,
    source,
  });

  const request = new Request(
    getVendooServerBasePath("/api/rest/v1/auto/pull"),
    options
  );

  const response = await sendServerRequest(request);

  return assertResponse(response);
}

/**
 * Send to the server the result of an executed instruction.
 */
export async function notifyCommandResults({
  deviceId,
  instruction,
  response,
  source,
}: {
  deviceId: string;
  instruction: AutopilotInstructionType;
  response: AnyCommand;
  source: AutopilotPullSourceType;
}): Promise<void> {
  const canRun = await VendooExtensionSessionStore().prepareSessionCookies();
  if (!canRun) return;

  const options: RequestInit = await getRequestOptions({
    deviceId,
    instruction,
    response,
    source,
  });

  const request = new Request(
    getVendooServerBasePath("/api/rest/v1/auto/notify"),
    options
  );

  await sendServerRequest(request);
}

export async function notifyCommandBundle(
  bundle: AutopilotNotifyBundleRequestType
) {
  const canRun = await VendooExtensionSessionStore().prepareSessionCookies();
  if (!canRun || !bundle.length) return;

  const options: RequestInit = await getBundleRequestOptions(bundle);

  const request = new Request(
    getVendooServerBasePath("/api/rest/v1/auto/notify"),
    options
  );

  await sendServerRequest(request);
}
