import { queryCommands } from "@vendoo/extension-v3/src/serviceWorker/queue/utils";
import { LoggerType } from "@vendoo/common/logger2/constructor";
import { upsertDeviceId } from "../device";
import { AutopilotPullSourceType } from "@vendoo/common/schemas/server/autopilot";
import processInstructionsBundled from "./bundled";
import processInstructionsSingled from "./singled";

/**
 * This function reaches out to the server pulling a batch of commands and executing it.
 * All executions are sent back to the server with the result.
 */
export async function pullNextCommands({
  source,
  logger,
}: {
  source: AutopilotPullSourceType;
  logger: LoggerType;
}) {
  logger = logger.extend("pullNextCommands");

  logger.debug("Executing");

  const deviceId = await upsertDeviceId({ logger });
  const { instructions, shouldBundle } = await queryCommands(deviceId, source);

  if (shouldBundle) {
    return await processInstructionsBundled(
      { logger, deviceId, source },
      instructions
    );
  }

  await processInstructionsSingled({ logger, deviceId, source }, instructions);
}
