import { LoggerType } from "@vendoo/common/logger2/constructor";
import {
  HandledErrorType,
  handleException,
} from "@vendoo/common/errors/handle";

import { EventHandlerType } from "../types";

import { commandHandlers } from "./commands";
import {
  CommandHandlerKey,
  AnyCommand,
  AnyCommandResult,
  AnyCommandHandler,
  PortLikeType,
} from "./types";

const getCommandHandler = (commandName: CommandHandlerKey) => {
  return commandHandlers[commandName];
};

export type DispatcherDeps = {
  logger: LoggerType;
  type: EventHandlerType;
};

export const dispatch = (
  { logger: parentLogger, type }: DispatcherDeps,
  {
    message,
    msgPort,
  }: {
    message: AnyCommand;
    msgPort: PortLikeType;
  }
) => {
  const logger = parentLogger.extend("Dispatcher");
  logger.debug("Received message", {
    type,
    portName: msgPort.name,
    messageId: message.id,
    messageType: message.type,
    messageName: message.name,
  });

  // Function to reply to a received message
  const reply = ({
    result,
    error,
  }: {
    result?: AnyCommandResult;
    error?: Error | HandledErrorType;
  }) => {
    try {
      msgPort.postMessage({
        ...message,
        result,
        error,
      });
    } catch (err) {
      handleException(err);
      logger.debug("Error replying", {
        type,
        portName: msgPort.name,
        messageId: message.id,
        messageType: message.type,
        messageName: message.name,
      });
    }
  };

  const handler = getCommandHandler(message.name) as AnyCommandHandler;

  if (!handler) {
    return reply({
      error: new Error(`No handler for ${message.type} ${message.name}`),
    });
  }

  return handler(message.payload, message, msgPort)
    .then(result => {
      logger.debug("Message result", {
        type,
        portName: msgPort.name,
        messageId: message.id,
        messageType: message.type,
        messageName: message.name,
        result,
      });

      reply({ result });
    })
    .catch(err => {
      const error = handleException(err);
      logger.debug("Error processing message", {
        type,
        portName: msgPort.name,
        messageId: message.id,
        messageType: message.type,
        messageName: message.name,
        errorMessage: err.message,
      });
      return reply({ error });
    });
};

export const createServiceDispatcher = ({ logger, type }) => (
  message: AnyCommand,
  msgPort: chrome.runtime.Port
) => {
  return dispatch({ logger, type }, { message, msgPort });
};
