import * as uuid from "uuid";
import { LoggerType } from "@vendoo/common/logger2/constructor";
import VendooAPIServerCookies from "@vendoo/extension-v3/src/common/chrome/serverCookies";

/**
 * Class that manages the Vendoo device ID cookie.
 */
const VendooDeviceStore = () => {
  const cookieName = "vdid";
  const vendooAPIServerCookies = VendooAPIServerCookies({
    url: process.env.VENDOO_SERVER_ENDPOINT!,
    setOnDomain: false,
  });

  // cookieName, get, set
  return {
    cookieName,
    get: () => vendooAPIServerCookies.get(cookieName),
    set: (value: string) => vendooAPIServerCookies.set(cookieName, value),
  };
};

/**
 * This function is used to set a device ID cookie from the
 *  extension service worker, using chrome.cookies API.
 *
 * This cookie is used to identity this device on the server side.
 * If there is not already a cookie set, it will create one randomly
 *  using the uuid library (uuid-v4).
 *
 * The cookie name is vdid which stands for "Vendoo Device ID"
 */
export async function upsertDeviceId({ logger }: { logger: LoggerType }) {
  logger = logger.extend("upsertDeviceId");

  const deviceStore = VendooDeviceStore();

  const deviceId = await deviceStore.get();

  if (deviceId) {
    logger.debug("Device ID found", { deviceId });
    return deviceId;
  }

  logger.debug("No Device ID found, creating one");

  const nextDeviceId = await deviceStore.set(uuid.v4().split("-")[0]);

  if (!nextDeviceId)
    // This is not supposed to happen, this assertion is mostly for type checking
    throw new Error("Unable to create device ID");

  logger.info("Device ID created", { nextDeviceId });
  return nextDeviceId;
}
