export const REGION_COOKIE_NAME = "__ven_reg";

export function createRegionHeader(
  regionID: VendooRegionIDs
): Record<string, string>;
export function createRegionHeader(
  getRegionID: () => VendooRegionIDs
): Record<string, string>;

export function createRegionHeader(regionIDOrCB): Record<string, string> {
  const regionID =
    typeof regionIDOrCB === "function" ? regionIDOrCB() : regionIDOrCB;

  if (!regionID) return {};

  return {
    [`X-Ven-UHS-${regionID}`]: "true",
  };
}
