import "../common/setup/serviceWorker";
import "./queue";

import { Logger } from "@vendoo/common/context/shared/resolve";
import { EventHandlerType } from "./types";
import { createServiceDispatcher } from "./services/dispatcher";

const setupConnection = (type: EventHandlerType) => {
  const logger = Logger()
    .extend("ServiceWorker")
    .trace({ extensionId: chrome.runtime.id });

  logger.info("Extension Process Started");

  return (port: chrome.runtime.Port) => {
    const connectionLogger = logger.extend("Connection");
    const serviceDispatcher = createServiceDispatcher({ logger, type });

    connectionLogger.debug("[ServiceWorker:Connection] connection received", {
      type,
      portName: port.name,
    });

    port.onDisconnect.addListener(port => {
      connectionLogger.debug("[ServiceWorker:Connection] connection closed", {
        type,
        portName: port.name,
      });
    });

    port.onMessage.addListener((message, msgPort) => {
      connectionLogger.debug("[ServiceWorker:Connection] message received", {
        type,
        portName: port.name,
        message,
      });

      serviceDispatcher(message, msgPort);
    });
  };
};

chrome.runtime.onConnectExternal.addListener(setupConnection("external"));

let vendooUrls: string[] = [];
switch (process.env.GATSBY_WORK_ENV) {
  case "local":
    vendooUrls = [
      "*://localhost:*/app/onboarding*",
      "*://localhost:*/app/settings/*",
    ];
    break;
  case "dev":
    vendooUrls = [
      "*://dev.vendoo.co/app/onboarding*",
      "*://dev.vendoo.co/app/settings/*",
    ];
    break;
  case "staging":
    vendooUrls = [
      "*://staging.vendoo.co/app/onboarding*",
      "*://staging.vendoo.co/app/settings/*",
    ];
    break;
  case "prod":
    vendooUrls = [
      "*://web.vendoo.co/app/onboarding*",
      "*://web.vendoo.co/app/settings/*",
    ];
    break;
  default:
    break;
}
chrome.tabs.query({ url: vendooUrls }, function(tabs) {
  tabs.forEach(tab => {
    if (!tab.id) return;
    chrome.tabs.reload(tab.id);
  });
});
