import { getCookieDomainFromOrigin } from "@vendoo/common/cookies";

const getCookie = (domain: string, name: string) =>
  chrome.cookies
    .get({
      url: domain,
      name,
    })
    .then(cookie => cookie?.value);

const getCookieData = (domain: string, name: string) =>
  chrome.cookies
    .get({
      url: domain,
      name,
    })
    .then(cookie => cookie);

const setCookie = (
  { url, domain }: { url: string; domain?: string },
  name: string,
  value: string,
  expirationDate: number = Date.now() / 1000 + 60 * 60 * 24 * 365 * 10
) =>
  chrome.cookies
    .set({
      url,
      domain,
      name,
      value,
      path: "/",
      httpOnly: true,
      secure: true,
      sameSite: "strict",
      expirationDate,
    })
    .then(cookie => cookie?.value);

const VendooAPIServerCookies = (deps?: {
  url: string;
  setOnDomain: boolean;
}) => {
  const url = deps?.url || process.env.VENDOO_SERVER_ENDPOINT!;
  const domain = deps?.setOnDomain ? getCookieDomainFromOrigin(url) : undefined;

  return {
    set: setCookie.bind(0, { url, domain }),
    get: getCookie.bind(0, url),
    getData: getCookieData.bind(0, url),
  };
};

export default VendooAPIServerCookies;
