import { ExtensionV3InterceptRequestBodyCommand } from "@vendoo/common/messaging/connection/types";
import { createTab } from "@vendoo/extension-v3/src/common/chrome/createTab";

export const interceptNetworkRequest = (
  payload: ExtensionV3InterceptRequestBodyCommand["payload"],
  message: ExtensionV3InterceptRequestBodyCommand
) =>
  new Promise<ExtensionV3InterceptRequestBodyCommand["result"]>(resolve => {
    createTab({
      url: payload.config?.url!,
      active: false,
    }).then(tab => {
      if (!tab.id) throw new Error("ExtV3: Unable to open tab");
      // In case the interception script doesn't reply in 15 seconds, we close the tab.
      let timeout: NodeJS.Timeout | null = setTimeout(() => {
        chrome.tabs.remove(tab.id!).catch(() => {});
      }, 15000);

      chrome.tabs.sendMessage(
        tab.id,
        message,
        (response: ExtensionV3InterceptRequestBodyCommand["result"]) => {
          resolve(response!);
          chrome.tabs.remove(tab.id!).catch(() => {});

          if (timeout) {
            clearTimeout(timeout);
            timeout = null;
          }
        }
      );
    });
  });
