import { ExtensionV3PingCommand } from "@vendoo/common/messaging/connection/types";

export const ping = (
  { deviceId }: ExtensionV3PingCommand["payload"],
  _message: ExtensionV3PingCommand
): Promise<ExtensionV3PingCommand["result"]> =>
  Promise.resolve({
    deviceId,
    timestamp: new Date().getTime(),
  });
