import { init } from "@vendoo/extension-v3/src/common/setup/serviceWorker";
import { Logger } from "@vendoo/common/context/shared/resolve";
import { LoggerType } from "@vendoo/common/logger2/constructor";

import {
  captureException,
  getLastRun,
  setLastRun,
} from "@vendoo/extension-v3/src/serviceWorker/queue/utils";

import { AutopilotPullSourceType } from "@vendoo/common/schemas/server/autopilot";
import { pullNextCommands } from "./pull";

/**
 * See DR: https://www.notion.so/Decision-Extension-Queue-pull-interval-of-5-minutes-a9c0dc6ee05d49218c325a7191c2e57e
 */
const QUEUE_INTERVAL_IN_MINUTES = 5;
const QUEUE_DELAY_IN_MINUTES = 5;

const ALARM_NAME = "VendooQueuePulling";

async function QueueLogger(from: string) {
  await init;

  return Logger()
    .extend("queue")
    .extend(from);
}

async function canRunPull({ logger }: { logger: LoggerType }) {
  const lastRun = await getLastRun({ logger });
  return {
    lastRun,
    canRun: lastRun
      ? Date.now() - lastRun >= QUEUE_INTERVAL_IN_MINUTES * 60 * 1000 - 6000
      : true,
  };
}

/** Pull next commands on alerts and reloads, and logs success/failure */
async function start({
  source,
  logger,
}: {
  source: AutopilotPullSourceType;
  logger: LoggerType;
}) {
  try {
    logger.info("Extension Queue triggered");

    const { lastRun, canRun } = await canRunPull({ logger });
    if (!canRun) {
      logger.warn("Extension Pull Queue avoided because it ran recently", {
        lastRun,
      });
      return;
    }

    await setLastRun();

    logger.debug("About to start pulling");

    await pullNextCommands({
      source,
      logger,
    });

    logger.info("Finished pulling/executing successfully");
  } catch (err) {
    logger.warn("Error while pulling/executing commands", {}, err);
    throw err;
  }
}

function alarmListener({ name }) {
  return captureException(async () => {
    const logger = await QueueLogger("onAlarm");
    logger.info("Alarm triggered", { name });
    if (name !== ALARM_NAME) {
      logger.warn("Unknown alarm name", { name });
      return;
    }

    await start({
      source: "extv3:onAlarm",
      logger,
    });
  })();
}

function startOnWakeup() {
  return captureException(async () => {
    const logger = await QueueLogger("setTimeout");
    logger.info("Wakeup triggered");

    await start({
      source: "extv3:setTimeout",
      logger,
    });
  })();
}

async function createVendooPullingAlarm({ logger }: { logger: LoggerType }) {
  const alarmOptions = {
    delayInMinutes: QUEUE_DELAY_IN_MINUTES,
    periodInMinutes: QUEUE_INTERVAL_IN_MINUTES,
  };

  try {
    // Promise.resolve to solve lint issues
    // documentation says it returns a promise
    // https://developer.chrome.com/docs/extensions/reference/alarms/#method-create
    await chrome.alarms.clearAll();
    await Promise.resolve(chrome.alarms.create(ALARM_NAME, alarmOptions));

    logger.info("Successfully created alarm", {
      alarmName: ALARM_NAME,
      alarmOptions: JSON.stringify(alarmOptions),
    });

    return true;
  } catch (err) {
    logger.warn(
      "Error while creating alarm",
      {
        alarmOptions: JSON.stringify(alarmOptions),
      },
      err
    );
    return false;
  }
}

function checkAlarmsAndCreatedIfNeeded() {
  return new Promise<void>((resolve, reject) => {
    chrome.alarms.get(ALARM_NAME, async alarm => {
      try {
        const logger = await QueueLogger("checkAlarmsAndCreatedIfNeeded");
        if (!alarm) {
          logger.warn("Alarm should exists and was not found");
          await createVendooPullingAlarm({ logger });
          resolve();
          return;
        }

        const { lastRun } = await canRunPull({ logger });
        if (!lastRun) {
          logger.warn(
            "Alarm exists but did not run yet, alarm will not be reset"
          );
          resolve();
          return;
        }

        const moreThanOneDay = Date.now() - lastRun > 24 * 60 * 60 * 1000;
        if (alarm && moreThanOneDay) {
          logger.warn("Last run was more than 24 hours ago, resetting alarm");
          await createVendooPullingAlarm({ logger });
          resolve();
          return;
        }

        logger.info(
          "Alarm exists and it should be running fine in the last 24 hours"
        );
        resolve();
        return;
      } catch (err) {
        reject(err);
      }
    });
  });
}

chrome.runtime.onInstalled.addListener(
  captureException(async () => {
    const logger = await QueueLogger("onInstalled");
    logger.info("Extension installed, clearing alarms and creating new one");
    await createVendooPullingAlarm({ logger });
  })
);

chrome.alarms.onAlarm.addListener(alarmListener);

setTimeout(captureException(startOnWakeup), 5000);
setTimeout(captureException(checkAlarmsAndCreatedIfNeeded), 10000);
