import { ExtensionV3ExecPageScriptCommand } from "@vendoo/common/messaging/connection/types";
import { createTab } from "@vendoo/extension-v3/src/common/chrome/createTab";

export const execPageScript = (
  payload: ExtensionV3ExecPageScriptCommand["payload"],
  message?: ExtensionV3ExecPageScriptCommand
) =>
  new Promise<ExtensionV3ExecPageScriptCommand["result"]>(resolve => {
    createTab({
      url: payload.url,
      active: !!payload.activeTab,
    }).then(tab => {
      if (!tab.id) throw new Error("ExtV3: Unable to open tab");
      chrome.tabs.sendMessage(
        tab.id,
        message,
        (response: ExtensionV3ExecPageScriptCommand["result"]) => {
          resolve(response);
          if (payload.closeOnResolve && tab.id) chrome.tabs.remove(tab.id);
        }
      );
    });
  });
