import { Logger } from "@vendoo/common/context/shared/resolve";
import { ExtensionV3RequestEventSubscribeCommand } from "@vendoo/common/messaging/connection/types";
import { PortLikeType } from "@vendoo/extension-v3/src/serviceWorker/services/types";
import { getEventForwarder } from "./listener";

export const requestEventSubscribe = async (
  _payload: ExtensionV3RequestEventSubscribeCommand["payload"],
  message: ExtensionV3RequestEventSubscribeCommand,
  msgPort: PortLikeType
) => {
  const logger = Logger().extend("subscribe");
  logger.info("Subscribing request event listener", message);

  chrome.webRequest.onBeforeRequest.addListener(
    getEventForwarder(msgPort),
    { types: ["xmlhttprequest"], urls: message.payload.urls },
    ["requestBody"]
  );
};
