import { LoggerType } from "../logger2/constructor";

/** Creates a promise with its resolution methods extracted from the factory */
export interface OpenPromise<T> {
  status: "pending" | "resolved" | "rejected";
  promise: Promise<T>;
  resolve: (res: T) => void;
  reject: (err: Error) => void;
}

export function openPromise<T, J extends OpenPromise<T> = OpenPromise<T>>({
  timeout,
}: {
  timeout?: number;
  logger?: LoggerType;
} = {}): J {
  const access: Partial<J> = {};
  access.promise = new Promise((resolve, reject) => {
    access.status = "pending";
    access.resolve = data => {
      if (access.status !== "pending") return;
      access.status = "resolved";
      resolve(data);
    };
    access.reject = err => {
      if (access.status !== "pending") return;
      access.status = "rejected";
      reject(err);
    };

    if (!timeout) return;

    setTimeout(() => {
      access.reject && access.reject(new Error("Timeout"));
    }, timeout);
  });
  return access as J;
}
