import { sharedContext, sharedTypes } from "@vendoo/common/context/shared";
import { upsertDeviceId } from "@vendoo/extension-v3/src/serviceWorker/queue/device";
import { getExtensionLogger } from "../logger/index";

export const init = (async () => {
  try {
    const baseLogger = getExtensionLogger("extensionV3ServiceWorker");
    sharedContext.bind.value(sharedTypes.Logger, baseLogger);

    baseLogger.info("Extension Service Worker logger initialized");

    const deviceId = await upsertDeviceId({ logger: baseLogger });

    const extensionLogger = baseLogger.trace({
      deviceId,
    });

    sharedContext.bind.rebind.value(sharedTypes.Logger, extensionLogger);
  } catch (err) {
    console.warn("Error while getting the device ID" + err);
  }
})();
