import { Logger } from "@vendoo/common/context/shared/resolve";
import { ExtensionV3Event } from "@vendoo/common/messaging/connection/types";
import { PortLikeType } from "@vendoo/extension-v3/src/serviceWorker/services/types";

export const getEventForwarder = (
  port: PortLikeType,
  eventName: ExtensionV3Event["name"]
) => {
  let timeoutId;
  const delay = 2000;
  return (changeInfo: chrome.cookies.CookieChangeInfo) => {
    const logger = Logger().extend("listener");
    if (changeInfo.cookie.domain.includes("localhost")) return;

    logger.info("Forwarding events", { portName: port.name, event: eventName });
    const event = {
      type: "event",
      name: eventName,
      payload: changeInfo,
    };
    if (timeoutId) clearTimeout(timeoutId);
    timeoutId = setTimeout(() => port.postMessage(event), delay);
  };
};
