import buildFullPath from "axios/lib/core/buildFullPath";
import buildURL from "axios/lib/helpers/buildURL";
import isObject from "lodash/isObject";

import { VendooRequestConfigType } from "@vendoo/common/types/sendWebRequest";

const applyBasicAuthIfNeeded = (
  axiosRequestConfig: VendooRequestConfigType,
  headers: Headers
) => {
  if (axiosRequestConfig.auth) {
    const username = axiosRequestConfig.auth.username || "";
    const password = axiosRequestConfig.auth.password
      ? decodeURI(encodeURIComponent(axiosRequestConfig.auth.password))
      : "";

    headers.set("Authorization", `Basic ${btoa(username + ":" + password)}`);
  }
};

const setHeaders = (
  headers: Headers,
  axiosRequestConfig: VendooRequestConfigType
) => {
  // In these cases the browser will automatically set the correct Content-Type,
  // but only if that header hasn't been set yet. So that's why we're deleting it.
  if (axiosRequestConfig.data instanceof FormData) {
    headers.delete("Content-Type");
  } else if (!headers.get("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }
};

const parseBody = (axiosRequestConfig: VendooRequestConfigType) => {
  if (!axiosRequestConfig.data) return null;
  let body = axiosRequestConfig.data;

  if (
    isObject(body) &&
    !(body instanceof Blob) &&
    !(body instanceof File) &&
    !(body instanceof FormData)
  )
    body = JSON.stringify(body);

  return body;
};

export const createFetchRequest = (
  axiosRequestConfig: VendooRequestConfigType
) => {
  const headers = new Headers(axiosRequestConfig.headers);

  // HTTP basic authentication
  applyBasicAuthIfNeeded(axiosRequestConfig, headers);

  // Method will be 'get' be default
  const method = axiosRequestConfig.method!.toUpperCase();

  if (method !== "GET" && method !== "HEAD") {
    setHeaders(headers, axiosRequestConfig);
  }

  const options: RequestInit = {
    headers,
    method,
    body: parseBody(axiosRequestConfig),
  };

  options.credentials =
    axiosRequestConfig.withCredentials ||
    axiosRequestConfig.withCredentials === undefined
      ? "include"
      : "omit";

  const fullPath = buildFullPath(
    axiosRequestConfig.baseURL,
    axiosRequestConfig.url
  );
  const url = buildURL(
    fullPath,
    axiosRequestConfig.params,
    axiosRequestConfig.paramsSerializer
  );

  // Expected browser to throw error if there is any wrong configuration value
  return new Request(url, options);
};
