import { VendooRequestConfigType } from "@vendoo/common/types/sendWebRequest";

const axiosDefaults = {
  timeout: 0,
  xsrfCookieName: "XSRF-TOKEN",
  xsrfHeaderName: "X-XSRF-TOKEN",
  responseType: "json",
  responseEncoding: "utf8",
  withCredentials: undefined,
  method: "get",
};
// Apply axios default config to the incomming axios request type using VendooRequestConfigType
export const axiosRequestWithDefaults = (
  config: VendooRequestConfigType
): VendooRequestConfigType => {
  return Object.assign({}, axiosDefaults, config);
};
