import { SESSION_COOKIE_NAMES } from "@vendoo/common/cookies/constants";
import { REGION_COOKIE_NAME } from "@vendoo/common/request/loadBalancer";
import VendooAPIServerCookies from "@vendoo/extension-v3/src/common/chrome/serverCookies";

type ExtensionSessionDepsType = {
  enterpriseCookies: ReturnType<typeof VendooAPIServerCookies>;
  webCookies: ReturnType<typeof VendooAPIServerCookies>;
  deprecatedApiCookies?: ReturnType<typeof VendooAPIServerCookies>;
  deprecatedWebCookies?: ReturnType<typeof VendooAPIServerCookies>;
};

const getFallbackSession = async ({
  enterpriseCookies,
  deprecatedApiCookies,
  deprecatedWebCookies,
}: {
  enterpriseCookies: ReturnType<typeof VendooAPIServerCookies>;
  deprecatedApiCookies?: ReturnType<typeof VendooAPIServerCookies>;
  deprecatedWebCookies?: ReturnType<typeof VendooAPIServerCookies>;
}) => {
  const sessionDeprecatedWeb = await Promise.race(
    SESSION_COOKIE_NAMES.map(cookieName =>
      deprecatedWebCookies?.getData(cookieName).catch(() => undefined)
    )
  );

  if (sessionDeprecatedWeb) {
    return sessionDeprecatedWeb;
  }

  const sessionDeprecatedApi = await Promise.race(
    SESSION_COOKIE_NAMES.map(cookieName =>
      deprecatedApiCookies?.getData(cookieName).catch(() => undefined)
    )
  );

  if (sessionDeprecatedApi) {
    return sessionDeprecatedApi;
  }

  const sessionEnterprise = await Promise.race(
    SESSION_COOKIE_NAMES.map(cookieName =>
      enterpriseCookies.getData(cookieName).catch(() => undefined)
    )
  );

  return sessionEnterprise;
};

const prepareSessionCookies = async ({
  webCookies,
  enterpriseCookies,
  deprecatedApiCookies,
  deprecatedWebCookies,
}: ExtensionSessionDepsType) => {
  const fallbackSession = await getFallbackSession({
    enterpriseCookies,
    deprecatedApiCookies,
    deprecatedWebCookies,
  });

  const sessionWebapp = await Promise.race(
    SESSION_COOKIE_NAMES.map(cookieName => webCookies.getData(cookieName))
  );

  /**
   * If we have a session in the enterprise or in the old domain api server, we should use it in the web session
   * This will auto auth the user on the new api of the web app.
   * Currently, we are doing requests to the server and we need the extension authenticated for that.
   */
  if (fallbackSession && !sessionWebapp) {
    await Promise.all(
      SESSION_COOKIE_NAMES.map(cookieName =>
        webCookies.set(
          cookieName,
          fallbackSession.value,
          fallbackSession.expirationDate
        )
      )
    );
  }

  return Boolean(fallbackSession || sessionWebapp);
};

const getRegion = async (
  deps: ExtensionSessionDepsType
): Promise<VendooRegionIDs> => {
  const regionStored = (
    await Promise.all([
      deps.webCookies.get(REGION_COOKIE_NAME),
      deps.enterpriseCookies.get(REGION_COOKIE_NAME),
    ])
  ).filter(region => Boolean(region))[0];

  const region = (regionStored || "us") as VendooRegionIDs;
  return region;
};

export const VendooExtensionSessionStore = () => {
  const localCookiesURL = String(process.env.VENDOO_SERVER_ENDPOINT).includes(
    "localhost"
  )
    ? "https://dev.vendoo.co"
    : process.env.VENDOO_SERVER_ENDPOINT!;

  const deprecatedWebCookies =
    process.env.GATSBY_WORK_ENV === "prod"
      ? VendooAPIServerCookies({
          url: "https://web.vendoo.co",
          setOnDomain: true,
        })
      : VendooAPIServerCookies({
          url: localCookiesURL,
          setOnDomain: true,
        });

  const deprecatedApiCookies =
    process.env.GATSBY_WORK_ENV === "prod"
      ? VendooAPIServerCookies({
          url: "https://api.vendoo.co",
          setOnDomain: true,
        })
      : undefined;

  const enterpriseCookies = VendooAPIServerCookies({
    url: process.env.VENDOO_ENTERPRISE_API_ENDPOINT!,
    setOnDomain: true,
  });

  const webCookies = VendooAPIServerCookies({
    url: process.env.VENDOO_SERVER_ENDPOINT!,
    setOnDomain: true,
  });

  const deps: ExtensionSessionDepsType = {
    webCookies,
    enterpriseCookies,
    deprecatedApiCookies,
    deprecatedWebCookies,
  };

  return {
    prepareSessionCookies: prepareSessionCookies.bind(0, deps),
    getRegion: getRegion.bind(0, deps),
  };
};
