import {
  AutopilotPullResponseSchema,
  AutopilotPullSourceType,
} from "@vendoo/common/schemas/server/autopilot";

import { LoggerType } from "@vendoo/common/logger2/constructor";
import { openPromise } from "@vendoo/common/utils/open-promise";
import { dispatch } from "../../services/dispatcher";
import { AnyCommand } from "../../services/types";
import { notifyCommandBundle } from "../utils";

import { from } from "rxjs/internal/observable/from";
import { bufferTime } from "rxjs/internal/operators/bufferTime";
import { map } from "rxjs/internal/operators/map";
import { mergeMap } from "rxjs/internal/operators/mergeMap";
import { lastValueFrom } from "rxjs/internal/lastValueFrom";

export default function processInstructionsBundled(
  {
    logger,
    deviceId,
    source,
  }: { logger: LoggerType; deviceId: string; source: AutopilotPullSourceType },
  instructions: AutopilotPullResponseSchema["instructions"]
): Promise<void> {
  const dispatcher = dispatch.bind(0, {
    logger,
    type: "queue",
  });

  return lastValueFrom(
    from(instructions).pipe(
      mergeMap(async instruction => {
        const action = instruction.command as AnyCommand;
        const future = openPromise<AnyCommand>();
        const req = dispatcher({
          message: action,
          msgPort: { name: "queue", postMessage: future.resolve },
        });

        const [response] = await Promise.all([future.promise, req]);
        return [instruction, response] as const;
      }, 4),
      map(([instruction, response]) => ({
        deviceId,
        instruction,
        response,
        source,
        timestamp: Date.now(),
        serviceWorkerInstanceID: undefined,
      })),
      bufferTime(3000),
      mergeMap(notifyCommandBundle)
    )
  );
}
