import asFormData from "json-form-data";
import get from "lodash/get";

import { safeParse } from "../safeParse";

// Types
import { FormDataPropsType } from "./types";
// Types
import { VendooTransformRequestOrderType } from "@vendoo/common/types/sendWebRequest";

export const formData = ({ data, order }: FormDataPropsType) => {
  if (order) {
    const orderParsed = safeParse<VendooTransformRequestOrderType>(order, []);
    let formData = new FormData();

    for (let pathField of orderParsed) {
      const value = get(data, pathField);
      formData.append(pathField, value);
    }
    return formData;
  }

  return asFormData(data);
};
