import { Logger } from "@vendoo/common/context/shared/resolve";
import { ExtensionV3EventSubscribeCommand } from "@vendoo/common/messaging/connection/types";
import { PortLikeType } from "@vendoo/extension-v3/src/serviceWorker/services/types";
import { getEventForwarder } from "./listener";

export const subscribe = async (
  _payload: ExtensionV3EventSubscribeCommand["payload"],
  message: ExtensionV3EventSubscribeCommand,
  msgPort: PortLikeType
) => {
  const logger = Logger().extend("subscribe");
  logger.info("Subscribing event listener", message);
  const eventHandler = getEventForwarder(msgPort, message.payload.event);
  const chromeEvent: any = message.payload.event
    .split(".")
    .reduce((obj, attr) => obj[attr], chrome);
  chromeEvent.addListener(eventHandler);
};
