import { LoggerType } from "@vendoo/common/logger2/constructor";
import {
  AutopilotPullSourceType,
  AutopilotPullResponseSchema,
} from "@vendoo/common/schemas/server/autopilot";
import { openPromise } from "@vendoo/common/utils/open-promise";
import { dispatch } from "../../services/dispatcher";
import { AnyCommand } from "../../services/types";
import { notifyCommandResults } from "../utils";

export default async function processInstructionsSingled(
  {
    logger,
    deviceId,
    source,
  }: {
    logger: LoggerType;
    deviceId: string;
    source: AutopilotPullSourceType;
  },
  instructions: AutopilotPullResponseSchema["instructions"]
): Promise<void> {
  const dispatcher = dispatch.bind(0, {
    logger,
    type: "queue",
  });
  for (const instruction of instructions) {
    const action = instruction.command as AnyCommand;
    const future = openPromise<AnyCommand>();

    const req = dispatcher({
      message: action,
      msgPort: {
        name: "queue",
        postMessage: future.resolve,
      },
    });

    const [response] = await Promise.all([future.promise, req]);

    try {
      await notifyCommandResults({
        deviceId,
        instruction,
        response,
        source,
      });

      logger.debug("Finished instruction and sent results to the server", {
        instruction_id: instruction.id,
        feature: instruction.feature,
        timestamp: instruction.timestamp,
        command_id: instruction.command.id,
        command_type: instruction.command.name,
      });

      logger.debug("Command Response", { response });
    } catch (err) {
      logger.warn("Error while notify results to the server", {}, err);
    }
  }
}
