import { Logger } from "@vendoo/common/context/shared/resolve";
import { ExtensionV3EventUnsubscribeCommand } from "@vendoo/common/messaging/connection/types";
import { getEventForwarder } from "./listener";

export const requestEventUnsubscribe = async (
  _payload: ExtensionV3EventUnsubscribeCommand["payload"],
  message: ExtensionV3EventUnsubscribeCommand,
  msgPort: chrome.runtime.Port
) => {
  const logger = Logger().extend("unsubscribe");
  logger.info("Unsubscribe request event listener", message);
  const eventHandler = getEventForwarder(msgPort);
  chrome.webRequest.onBeforeRequest.removeListener(eventHandler);
};
