const DOMAIN_REGEX = /^(?:api\.)?([a-z-]+\.)?([a-z-]+\.)?(vendoo.co)$/;

export const getCookieDomainFromOrigin = (originOrReferrer?: string) => {
  if (!originOrReferrer) {
    return undefined;
  }

  const url = new URL(
    originOrReferrer.startsWith("http")
      ? originOrReferrer
      : `https://${originOrReferrer}`
  );
  const matches = DOMAIN_REGEX.exec(url.hostname);
  if (!matches) {
    return undefined;
  }

  const result = matches.filter((_match, i) => i !== 0).join("");
  return result;
};
