const waitForTabReady = (tabId: number) =>
  new Promise<chrome.tabs.Tab>(resolve => {
    const onUpdateHandler = (
      updatedTabId: number,
      changeInfo: chrome.tabs.TabChangeInfo,
      tab: chrome.tabs.Tab
    ) => {
      if (tabId === updatedTabId && changeInfo.status === "complete") {
        chrome.tabs.onUpdated.removeListener(onUpdateHandler);
        resolve(tab);
      }
    };

    chrome.tabs.onUpdated.addListener(onUpdateHandler);
  });

type createTabParams = {
  url: string;
  active: boolean;
};

export const createTab = async ({ url, active }: createTabParams) => {
  const tab = await chrome.tabs.create({
    active,
    url,
  });

  if (!tab.id) throw new Error("ExtV3: Unable to open tab");

  return waitForTabReady(tab.id);
};
